export function Whitespace({
  spacing = {{spacing}},
  text = "{{text}}",
  accent = "{{accent}}",
  radius = {{radius}},
}) {
  const col = { flex: 1, background: "#FAF7F2", border: "1.5px dashed #24143055", borderRadius: 8, padding: 10, boxSizing: "border-box" };
  const label = { margin: "0 0 8px", fontSize: 11, color: "#241430aa" };
  const card = (mb) => ({ background: accent, borderRadius: radius, padding: 10, fontWeight: 600, fontSize: 11, boxSizing: "border-box", marginBottom: mb });
  return (
    <div style={{ font: "12px/1.4 system-ui, sans-serif", color: "#241430", width: 320 }}
      role="img" aria-label="Two identical stacks of cards side by side; the left uses tight fixed spacing, the right uses the adjustable generous spacing">
      <div style={{ display: "flex", gap: 16 }}>
        <div style={col}>
          <p style={label}>tight (8px)</p>
          <div style={card(8)}>{text}</div>
          <div style={card(8)}>{text}</div>
          <div style={card(0)}>{text}</div>
        </div>
        <div style={col}>
          <p style={label}>generous ({spacing}px)</p>
          <div style={card(spacing)}>{text}</div>
          <div style={card(spacing)}>{text}</div>
          <div style={card(0)}>{text}</div>
        </div>
      </div>
    </div>
  );
}
